    echo '<div class="panel"><h2>保存期間・集計</h2><div class="panel-body"><form method="post"><input type="hidden" name="action" value="save_settings">'.csrf_field().'<div class="form-grid"><label>ランキング対象期間（日）<input type="number" name="ranking_period_days" value="'.e(setting('ranking_period_days',3)).'"></label><label>相互RSS配分期間（時間）<input type="number" name="distribution_window_hours" value="'.e(setting('distribution_window_hours',24)).'"></label><label>生ログ保存（日）<input type="number" name="raw_retention_days" value="'.e(setting('raw_retention_days',180)).'"></label><label>配分履歴保存（日）<input type="number" name="distribution_retention_days" value="'.e(setting('distribution_retention_days',180)).'"></label><label>集計保存（日）<input type="number" name="aggregate_retention_days" value="'.e(setting('aggregate_retention_days',1095)).'"></label><label>通常RSS記事保存（日）<input type="number" name="rss_item_retention_days" value="'.e(setting('rss_item_retention_days',3)).'"></label></div><button class="button primary">保存</button></form></div></div><div class="panel"><h2>ログイン情報変更</h2><div class="panel-body"><form method="post"><input type="hidden" name="action" value="change_password">'.csrf_field().'<label>ユーザー名<input name="new_username" value="'.e($_SESSION['admin_username']??'admin').'" required></label><label>現在のパスワード<input type="password" name="current_password" required></label><label>新しいパスワード（変更しない場合は空欄）<input type="password" name="new_password" minlength="10"></label><button class="button primary">変更</button></form></div></div><div class="panel"><h2>cron</h2><div class="panel-body"><pre class="codebox">'.e(app_url('cron/run.php?key='.$config['cron_key'])).'</pre><p>サーバーのcronを30分ごとに設定してください。</p></div></div>';
